:host {
  display: block;
  font-family: 'Google Sans', sans-serif;
  background-color: transparent;
color: #e3e3e3;

  app-storyboard {
    width: 100%;
    height: 100%;
    display: block;
    overflow: hidden;
  }
}

.workbench-container {
position: relative;
   --max-container-width: 1600px;
   background-color: transparent;
padding: 0 35px;
   max-width: var(--max-container-width);
   margin: 0 auto;
   margin-top: calc(5vh + 0px);
margin-left: max(calc(5vw + 4.5rem),
         calc(50% - var(--max-container-width) / 2));
}

.main-app-container {
  display: flex;
  flex-direction: column;
  gap: 12px; /* Spacing between cards */
}

::ng-deep .mat-mdc-chip-action,
::ng-deep .mat-mdc-chip-action-label {
overflow: hidden !important;
   text-overflow: ellipsis;
}

.beta-label {
display: flex;
   align-items: center;
   gap: 6px;
   padding: 6px 16px;
   background: rgba(255, 171, 64, 0.15);
      /* Amber A400 equivalent transparency */
   border: 1px solid rgba(255, 171, 64, 0.3);
   border-radius: 99px;
   color: #ffab40;
      /* Amber A400 */
   font-size: 0.75rem;
   font-weight: 700;
   letter-spacing: 0.05em;
   backdrop-filter: blur(8px);
   box-shadow: 0 4px 20px rgba(255, 171, 64, 0.1);
   z-index: 100;
   user-select: none;
   transition: all 0.3s ease;

&:hover {
      background: rgba(255, 171, 64, 0.25);
      border-color: rgba(255, 171, 64, 0.5);
      box-shadow: 0 4px 25px rgba(255, 171, 64, 0.2);
   }
}

.zoom-slider {
border: 1px solid rgba(193, 193, 193, 0.8);
   background: linear-gradient(180deg,
         rgba(126, 126, 126, 0.45) 0%,
         rgba(60, 60, 60, 0.16) 100%);
   box-shadow: 2px 2px 12px 0 rgba(0, 0, 0, 0.1);
   backdrop-filter: blur(7.5px);
}

.icon-btn {
background: radial-gradient(2373.18% 103.37% at 50% -3.37%,
         rgba(102, 102, 102, 0.38) 0%,
         rgba(60, 60, 60, 0.1) 100%);
   box-shadow:
      0 10px 15px 0 rgba(0, 0, 0, 0.25),
      0 1px 2.3px 0 rgba(255, 255, 255, 0.7) inset;
   backdrop-filter: blur(12px);
   transition: all 0.1s ease;
   border-radius: 50%;
   height: 2.5rem;
   width: 2.5rem;
padding: 8px;
}

.icon-btn.active {
background-color: #e3e3e3;
   border-radius: 10px;
padding: 8px;
}

::ng-deep .icon-btn.active mat-icon {
color: #444746 !important;
}

::ng-deep .icon-btn.active mat-icon svg {
fill: #444746 !important;
}

::ng-deep .icon-btn.active mat-icon svg path {
fill: #444746 !important;
}

.glass-bg-effect {
/* Matching .workflow-card style */
background: linear-gradient(180deg,
         rgba(255, 255, 255, 0.08) 0%,
         rgba(255, 255, 255, 0.02) 100%);
   border: 1px solid rgba(255, 255, 255, 0.1);
   border-radius: 12px;
   box-shadow: none;
      /* Workflow card has no shadow by default, only hover */
      backdrop-filter: blur(12px);
      /* Kept some blur as it looks good, though workflow card doesn't explicitly have it in the snippet provided, but it might be nice. */
}

.side-panel {
@extend .glass-bg-effect;
   display: flex;
   flex-direction: column;
   padding: 1rem;
   min-width: 24rem;
   max-width: 30rem;
min-height: 550px;
   max-height: 700px;
   border-radius: 12px;
   overflow-y: auto;
   scroll-behavior: smooth;

&.no-scroll {
      overflow-y: hidden;
   height: 700px;
   }
}

.drop-zone {
border: 2px dashed #666;
   border-radius: 8px;
   padding: 0.5rem;
   color: white;
   display: flex;
   align-items: center;
   justify-content: center;
   cursor: pointer;
   transition:
      border-color 0.3s,
      background-color 0.3s;
   background-color: #333;

&:hover {
      border-color: #007bff;
      background-color: #444;
   }

  img {
     max-width: 100%;
     max-height: 100%;
     object-fit: contain;
     border-radius: 6px;
  }
}

/* Custom Scrollbar for dark theme */
.custom-scrollbar::-webkit-scrollbar {
width: 4px;
   height: 6px;
}

.custom-scrollbar::-webkit-scrollbar-track {
background: transparent;
}

.custom-scrollbar::-webkit-scrollbar-thumb {
background: #333;
   border-radius: 4px;
}

.custom-scrollbar::-webkit-scrollbar-thumb:hover {
background: #555;
}

// Media Queries for responsiveness
@media (min-width: 375px) {
.title-font {
      font-size: 1.4rem;
   }
}

@media (min-width: 425px) {
.title-font {
      font-size: 1.7rem;
   }
}

@media (min-width: 576px) {
.title-font {
      font-size: 1.5rem;
   }
}

@media (min-width: 768px) {
.video-container {
      height: 45vh;
   }
}

@media (min-width: 1200px) {
.home-margin {
      margin: 2rem auto 0 auto;
   }

  ::ng-deep .image-selector-dialog {
     width: 70vw !important;
     max-width: 70vw !important;
  }
}

//boreders
.border {
border: 1px solid white;
}

/* Agent Chat Styles */
.chat-bubble {
max-width: 85%;
   padding: 10px 14px;
   border-radius: 16px;
   word-break: break-word;

&.user {
      background-color: #3b82f6;
      /* Blue */
      color: white;
      align-self: flex-end;
      border-bottom-right-radius: 4px;
   }

  &.agent {
   background: linear-gradient(135deg,
            rgba(255, 255, 255, 0.1) 0%,
            rgba(255, 255, 255, 0.05) 100%);
      color: #e3e3e3;
      align-self: flex-start;
      border-bottom-left-radius: 4px;
      border: 1px solid rgba(255, 255, 255, 0.1);
   }
}

.typing-indicator {
display: flex;
   gap: 4px;
   padding: 4px 0;
   align-items: center;

span {
      width: 6px;
      height: 6px;
   background-color: #e3e3e3;
      border-radius: 50%;
      animation: bounce 1.4s infinite ease-in-out both;

   &:nth-child(1) {
         animation-delay: -0.32s;
      }

