::ng-deep {
  /* Video Transitions */
  video {
    transition: none !important;
    opacity: 0 !important;
    visibility: hidden !important;
    z-index: -1 !important;
    pointer-events: none !important;

    &.transition-incoming {
      z-index: 10 !important;
      visibility: visible !important;
      pointer-events: auto !important;
    }

    &.transition-outgoing {
      z-index: 5 !important;
      visibility: visible !important;
      pointer-events: auto !important;
    }

    &[style*="opacity: 1"],
    &[style*="opacity:1"],
    &:not([style*="opacity: 0"]):not([style*="opacity:0"]):not(.transition-incoming):not(.transition-outgoing) {
      opacity: 1 !important;
      visibility: visible !important;
      z-index: 1 !important;
      pointer-events: auto !important;
    }
  }

  .transition-fade {
    &.transition-outgoing {
      opacity: calc(1 - var(--transition-progress, 0)) !important;
    }
    &.transition-incoming {
      opacity: var(--transition-progress, 0) !important;
    }
  }

  .transition-wipe_left {
    &.transition-outgoing {
      opacity: 1 !important;
    }
    &.transition-incoming {
      opacity: 1 !important;
      transform: translateX(var(--transition-translateX, 100%)) !important;
    }
  }

  .transition-wipe_right {
    &.transition-outgoing {
      opacity: 1 !important;
    }
    &.transition-incoming {
      opacity: 1 !important;
      transform: translateX(var(--transition-translateX, -100%)) !important;
    }
  }
}

// --- Audio clip gain & fade visuals ---

// Volume envelope drawn over the waveform: a rising wedge for fade-in and a
// falling wedge for fade-out. Width is bound inline (= fade seconds × px/s).
.audio-fade-ramp {
  position: absolute;
  top: 0;
  bottom: 0;
  pointer-events: none;
  background: rgba(0, 0, 0, 0.55);
  border-right: 1px dashed rgba(255, 255, 255, 0.35);

  &.audio-fade-ramp-in {
    left: 0;
    clip-path: polygon(0 0, 100% 0, 0 100%);
  }

  &.audio-fade-ramp-out {
    right: 0;
    border-right: none;
    border-left: 1px dashed rgba(255, 255, 255, 0.35);
    clip-path: polygon(0 0, 100% 0, 100% 100%);
  }
}

.audio-gain-badge {
  position: absolute;
  right: 4px;
  bottom: 3px;
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding: 1px 5px;
  border-radius: 9999px;
  font-size: 10px;
  font-weight: 600;
  line-height: 1;
  color: rgba(255, 255, 255, 0.9);
  background: rgba(0, 0, 0, 0.45);
  backdrop-filter: blur(4px);
  pointer-events: none;
  font-variant-numeric: tabular-nums;

  &.is-muted {
    color: #fca5a5;
  }
}
